function initNavbar(){const navbar=document.getElementById("navbar"),hamburger=document.getElementById("hamburger"),mobileMenu=document.getElementById("mobile-menu");let dropdownTimer;navbar&&window.addEventListener("scroll",function(){window.scrollY>40?navbar.classList.add("scrolled"):navbar.classList.remove("scrolled")},{passive:!0});const trigger=document.querySelector(".nav-services-trigger"),dropdown=document.querySelector(".nav-dropdown-panel");function closeMenu(){hamburger&&hamburger.classList.remove("open"),mobileMenu&&mobileMenu.classList.remove("open"),document.body.classList.remove("menu-open")}trigger&&dropdown&&(trigger.addEventListener("mouseenter",function(){clearTimeout(dropdownTimer),dropdown.classList.add("is-open")}),trigger.addEventListener("mouseleave",function(){dropdownTimer=setTimeout(function(){dropdown.matches(":hover")||dropdown.classList.remove("is-open")},100)}),dropdown.addEventListener("mouseenter",function(){clearTimeout(dropdownTimer)}),dropdown.addEventListener("mouseleave",function(){dropdownTimer=setTimeout(function(){dropdown.classList.remove("is-open")},100)})),hamburger&&mobileMenu&&(hamburger.addEventListener("click",function(){mobileMenu.classList.contains("open")?closeMenu():(hamburger&&hamburger.classList.add("open"),mobileMenu&&mobileMenu.classList.add("open"),document.body.classList.add("menu-open"))}),mobileMenu.querySelectorAll("a").forEach(function(link){link.addEventListener("click",closeMenu)}),document.addEventListener("click",function(e){!mobileMenu.classList.contains("open")||mobileMenu.contains(e.target)||hamburger.contains(e.target)||closeMenu()}))}